from work import *
c,h=witnesses(20);t=c
for a,b in {r'\unsure{en}':'en',r'^{\unsure{\cdot|\prime}}':r'^{\cdot}',r'\unsure{parmi}':'parmi',r'\unsure{Sup|sup}':'Sup',r'\unsure{question des frontières}':'question des frontières',r'\unsure{partie|parties}':'parties',r'\unsure{ds|dans}':'dans',r'\unsure{quelc|seule}':'quelc',r'\unsure{L|\mathscr{L}}':r'\mathcal L',r'\unsure{adh.}':'adh.',r'\unsure{f.}':'f.',r'\unsure{0|1}':'0',r'\deleted{\unsure{Dém}}':r'\deleted{\unsure{D|Dém}}',r'élément de $L$':r'élément de $\mathcal L$'}.items():t=t.replace(a,b)
